#!/usr/bin/env bun
/**
 * Isolated evidence capture for color-atmosphere r2.
 * Uses 127.0.0.1 + forced theme class; verifies tokens before each shot.
 */
import { $ } from "bun";
import { mkdir } from "node:fs/promises";

const OUT =
  "/Users/dhruv2mars/dev/github/portfolio/gauntlet/pieces/color-atmosphere/r2";
const BASE = "http://127.0.0.1:3000/";
const SESS = `ca-r2-${Date.now()}`;

await mkdir(OUT, { recursive: true });

async function ab(...args: string[]) {
  const r = await $`agent-browser --session ${SESS} ${args}`.nothrow();
  const out = (r.stdout.toString() + r.stderr.toString()).trim();
  console.log(out.slice(0, 800));
  return { code: r.exitCode, out };
}

function probe(theme: "dark" | "light") {
  return `(() => {
    const html = document.documentElement;
    html.classList.remove('dark','light');
    html.classList.add('${theme}');
    html.style.colorScheme = '${theme}';
    try { localStorage.setItem('portfolio-theme','${theme}'); } catch (e) {}
    window.scrollTo(0,0);
    const cs = getComputedStyle(html);
    const body = getComputedStyle(document.body);
    const bd = document.querySelector('.site-backdrop');
    const bds = bd ? getComputedStyle(bd) : null;
    return JSON.stringify({
      theme: html.classList.contains('${theme}') ? '${theme}' : 'fail',
      scrollY: window.scrollY,
      w: innerWidth,
      h: innerHeight,
      varBg: cs.getPropertyValue('--color-background').trim(),
      accent: cs.getPropertyValue('--color-accent').trim(),
      a4: cs.getPropertyValue('--color-activity-4').trim(),
      vignette: cs.getPropertyValue('--vignette-color').trim(),
      grain: cs.getPropertyValue('--grain-opacity').trim(),
      bodyBg: body.backgroundColor,
      bdBg: bds?.backgroundColor ?? null,
      h1: document.querySelector('h1')?.textContent ?? null,
      hasIntro: !!document.querySelector('.home-intro'),
      hasBackdrop: !!bd,
    });
  })()`;
}

await ab("close");
await ab("open", BASE);
await ab("set", "viewport", "1440", "900");
await ab("wait", "3000");

// Dark desktop
console.log("\n--- DARK DESKTOP ---");
let r = await ab("eval", probe("dark"));
if (!r.out.includes('"theme":"dark"') || !r.out.includes("Dhruv")) {
  throw new Error(`Dark probe failed: ${r.out}`);
}
await ab("wait", "500");
await ab("screenshot", `${OUT}/dark-home-desktop.png`);

// Light desktop
console.log("\n--- LIGHT DESKTOP ---");
r = await ab("eval", probe("light"));
if (!r.out.includes('"theme":"light"') || !r.out.includes("Dhruv")) {
  throw new Error(`Light probe failed: ${r.out}`);
}
// Expect light paper bg var
if (!r.out.includes("#f2f0ec") && !r.out.includes("242, 240, 236")) {
  console.warn("WARN: light --color-background may not match contract", r.out);
}
await ab("wait", "700");
await ab("screenshot", `${OUT}/light-home-desktop.png`);

// Dark mobile
console.log("\n--- DARK MOBILE ---");
await ab("set", "viewport", "390", "844");
await ab("wait", "800");
r = await ab("eval", probe("dark"));
if (!r.out.includes('"theme":"dark"') || !r.out.includes('"w":390')) {
  throw new Error(`Mobile probe failed: ${r.out}`);
}
await ab("wait", "500");
await ab("screenshot", `${OUT}/dark-home-mobile.png`);

await ab("close");
console.log("\nALL DONE →", OUT);
