@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

/*
  Visual system: "Ink Signal".
  Dark is the identity — warm ink depth, structural field, amber signal.
  One decisive accent (not portfolio blue / cyan / purple / cream+terracotta).
  Light is the same system inverted with equal craft.
  P2 owns color tokens + .site-backdrop only; fonts stay with P1.
*/
@theme {
  /* Ink Signal type — P1 owns these font tokens (r2: Fraunces display) */
  --font-display: var(--font-display-face), "Fraunces", ui-serif, Georgia, serif;
  --font-sans: var(--font-sans-face), "Schibsted Grotesk", ui-sans-serif,
    system-ui, sans-serif;
  --font-mono: var(--font-mono-face), "JetBrains Mono", ui-monospace, monospace;

  /* Warm ink depths — charcoal with brown undertone, not cold gray */
  --color-background: #07080b;
  --color-background-muted: #0e0c0a;
  --color-surface: #141210;
  --color-surface-hover: #1b1814;
  --color-foreground: #f0ebe4;
  --color-muted: #9a9288;
  --color-faint: #6e675e;
  --color-border: #2a2620;
  --color-border-strong: #3c352c;
  /* Signal amber — one decisive accent */
  --color-accent: #e8a23a;
  --color-accent-muted: #f0bf6a;
  --color-accent-foreground: #0a0908;
  --color-link: #f0ebe4;

  /* Heatmap — full amber ramp (empty → signal) */
  --color-activity-0: #161310;
  --color-activity-1: #3d2a0e;
  --color-activity-2: #6f4a12;
  --color-activity-3: #b0781c;
  --color-activity-4: #e8a23a;

  /* Atmosphere field tokens (consumed by .site-backdrop) */
  --field-color: rgb(232 162 58 / 0.055);
  --grid-color: rgb(240 235 228 / 0.045);
  --glow-color: rgb(232 162 58 / 0.16);
  --ink-wash: rgb(18 12 6 / 0.62);
  --vignette-color: rgb(0 0 0 / 0.62);
  --grain-opacity: 0.42;

  /* Motion language (P7) — quiet craft, three beats only */
  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-out-quad: cubic-bezier(0.25, 1, 0.5, 1);
  --duration-press: 140ms;
  --duration-hover: 160ms;
  --duration-theme: 240ms;
  --duration-enter: 420ms;
}

/* Light — same Ink Signal system inverted, not an afterthought */
.light {
  --color-background: #f2f0ec;
  --color-background-muted: #e8e4de;
  --color-surface: #faf8f5;
  --color-surface-hover: #ebe6df;
  --color-foreground: #14120e;
  --color-muted: #5c564c;
  --color-faint: #746c62;
  --color-border: #ddd6cc;
  --color-border-strong: #c4bbb0;
  --color-accent: #c47e1a;
  --color-accent-muted: #9a6010;
  --color-accent-foreground: #ffffff;
  --color-link: #14120e;

  --color-activity-0: #e6e1d8;
  --color-activity-1: #f0dfb8;
  --color-activity-2: #e8c878;
  --color-activity-3: #d49a2e;
  --color-activity-4: #c47e1a;

  --field-color: rgb(196 126 26 / 0.07);
  --grid-color: rgb(20 18 14 / 0.055);
  --glow-color: rgb(196 126 26 / 0.14);
  --ink-wash: rgb(232 226 216 / 0.7);
  --vignette-color: rgb(60 48 28 / 0.14);
  --grain-opacity: 0.28;
}

@layer base {
  html {
    color-scheme: dark;
    scroll-behavior: smooth;
  }

  html.light {
    color-scheme: light;
  }

  body {
    @apply bg-background text-foreground font-sans antialiased;
    font-feature-settings: "ss01" 1, "cv01" 1, "liga" 1, "calt" 1;
    text-rendering: optimizeLegibility;
    /* Theme surface crossfade — beat 2 */
    transition:
      background-color var(--duration-theme) var(--ease-out-quad),
      color var(--duration-theme) var(--ease-out-quad);
  }

  ::selection {
    background: color-mix(in srgb, var(--color-accent) 28%, transparent);
    color: var(--color-foreground);
  }

  a {
    @apply text-link;
  }

  :focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
    border-radius: 2px;
  }

  /* Hairlines should stay a single physical pixel */
  hr {
    border: 0;
    height: 1px;
    background: var(--color-border);
  }
}

/*
  Backdrop — Ink Signal atmosphere (P2).
  End-to-end depth: vignette + amber signal wash + structural grid/dots + film grain.
  No purple wash; grain/grid must read in both themes and on mobile.
*/
.site-backdrop {
  pointer-events: none;
  position: fixed;
  inset: 0;
  z-index: -1;
  overflow: hidden;
  background-color: var(--color-background);
  background-image:
    /* Edge vignette — pulls focus into the reading plane */
    radial-gradient(
      ellipse 92% 78% at 50% 38%,
      transparent 42%,
      var(--vignette-color) 100%
    ),
    /* Amber signal wash — top-left hero pool */
    radial-gradient(
      110% 65% at 28% -8%,
      color-mix(in srgb, var(--color-accent) 14%, transparent),
      transparent 58%
    ),
    /* Warm ink corner wash */
    radial-gradient(
      70% 50% at 0% 85%,
      var(--ink-wash),
      transparent 58%
    ),
    radial-gradient(
      65% 45% at 100% 100%,
      color-mix(in srgb, var(--color-background-muted) 85%, transparent),
      transparent 55%
    ),
    /* Structural grid — visible field lines */
    linear-gradient(var(--grid-color) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid-color) 1px, transparent 1px);
  background-size:
    auto,
    auto,
    auto,
    auto,
    48px 48px,
    48px 48px;
  background-position: center;
  transition: background-color var(--duration-theme) var(--ease-out-quad);
}

/* Film grain — SVG turbulence, opacity theme-tuned */
.site-backdrop::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.55'/%3E%3C/svg%3E");
  background-size: 180px 180px;
  opacity: var(--grain-opacity);
  mix-blend-mode: soft-light;
  pointer-events: none;
}

/* Amber glow pool + masked dot field on the upper reading plane */
.site-backdrop::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(
      55% 50% at 42% 12%,
      var(--glow-color),
      transparent 70%
    ),
    radial-gradient(var(--field-color) 0.95px, transparent 1px);
  background-size: auto, 22px 22px;
  background-repeat: no-repeat, repeat;
  mask-image: radial-gradient(
    ellipse 90% 60% at 50% 10%,
    black 18%,
    transparent 75%
  );
  pointer-events: none;
}

.skip-link {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.skip-link:focus {
  position: fixed;
  top: 0.75rem;
  left: 0.75rem;
  z-index: 50;
  width: auto;
  height: auto;
  margin: 0;
  clip: auto;
  overflow: visible;
  white-space: normal;
  border-radius: 9999px;
  border: 1px solid var(--color-border);
  background-color: var(--color-foreground);
  color: var(--color-background);
  padding: 0.5rem 0.875rem;
  font-size: 0.8125rem;
  font-weight: 500;
  outline: none;
}

/* Layout */
.container-site {
  @apply mx-auto w-full max-w-[46rem] px-5 sm:px-6;
}

/* Type — Ink Signal three-level system (P1 r2)
   1 Display: Fraunces, 64–80px desktop / 40–48px mobile, tight leading
   2 Body:    Schibsted 18px / generous leading
   3 Meta:    JetBrains Mono 11–12px, deliberate tracking
*/
.eyebrow,
